/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Float, GeneralizedMultivariateLogGammaDistribution, ImmutableDenseMatrix, IndexedBase, JointDistributionHandmade, Lambda, Matrix, MatrixSymbol, MultinomialDistribution, MultivariateBetaDistribution, MultivariateEwensDistribution, MultivariateLaplaceDistribution, MultivariateNormalDistribution, MultivariateTDistribution, NegativeMultinomialDistribution, NormalGammaDistribution, ProductSet, Reals, Relational, Sym, add, exp, fn, mul, pi, piecewise, pow, rational, round, symbols, xreplace } from '../../src';
import { sympyStr } from '../sympy-str';
import { equivalent } from '../sympy-equivalent';

describe("doctests of sympy.stats.joint_rv_types", () => {
  it("density(Gd)(y[0], y[1], y[2])", () => {
    const y_1 = new Sym('y_1', { positive: true });
    const y_2 = new Sym('y_2', { positive: true });
    const y_3 = new Sym('y_3', { positive: true });
    expect(equivalent(sympyStr(new GeneralizedMultivariateLogGammaDistribution([rational(1, 2), rational(1), ImmutableDenseMatrix(Matrix.of([[rational(1)], [rational(1)], [rational(1)]])), ImmutableDenseMatrix(Matrix.of([[rational(1)], [rational(1)], [rational(1)]]))]).call(y_1, y_2, y_3)), 'Sum(exp((n + 1)*(y_1 + y_2 + y_3) - exp(y_1) - exp(y_2) - exp(y_3))/(2**n*gamma(n + 1)**3), (n, 0, oo))/2', [y_1, y_2, y_3], { fn: '.__call__', input: 'GeneralizedMultivariateLogGammaDistribution(1/2, 1, Matrix([[1], [1], [1]]), Matrix([[1], [1], [1]]))' })).toBe(true);
  });
  it("density(G)(y[0], y[1], y[2])", () => {
    const y_1 = new Sym('y_1', { positive: true });
    const y_2 = new Sym('y_2', { positive: true });
    const y_3 = new Sym('y_3', { positive: true });
    expect(sympyStr(new GeneralizedMultivariateLogGammaDistribution([mul(rational(1, 2), pow(2, rational(1, 2))), rational(1), ImmutableDenseMatrix(Matrix.of([[rational(1)], [rational(1)], [rational(1)]])), ImmutableDenseMatrix(Matrix.of([[rational(1)], [rational(1)], [rational(1)]]))]).call(y_1, y_2, y_3))).toBe('sqrt(2)*Sum((1 - sqrt(2)/2)**n*exp((n + 1)*(y_1 + y_2 + y_3) - exp(y_1) - exp(y_2) - exp(y_3))/gamma(n + 1)**3, (n, 0, oo))/2');
  });
  it("density(N1)(1, 2)", () => {
    const x = new Sym('x');
    expect(sympyStr(new JointDistributionHandmade([Lambda([new IndexedBase(x, {}).at(rational(1)), new IndexedBase(x, {}).at(rational(2))], mul(rational(1, 2), pow(pi, -1), exp(add(rational(-1, 2), mul(rational(-1, 2), pow(new IndexedBase(x, {}).at(rational(1)), 2)), mul(rational(-1, 2), pow(new IndexedBase(x, {}).at(rational(2)), 2)), new IndexedBase(x, {}).at(rational(1)))))), ProductSet(Reals, Reals)]).call(rational(1), rational(2)))).toBe('exp(-2)/(2*pi)');
  });
  it("density(M)(x1, x2, x3)", () => {
    const p1 = new Sym('p1', { positive: true });
    const p2 = new Sym('p2', { positive: true });
    const p3 = new Sym('p3', { positive: true });
    const x1 = new Sym('x1', { nonnegative: true, integer: true });
    const x2 = new Sym('x2', { nonnegative: true, integer: true });
    const x3 = new Sym('x3', { nonnegative: true, integer: true });
    expect(sympyStr(new MultinomialDistribution([rational(3), ImmutableDenseMatrix(Matrix.of([[p1], [p2], [p3]]))]).call(x1, x2, x3))).toBe('Piecewise((6*p1**x1*p2**x2*p3**x3/(factorial(x1)*factorial(x2)*factorial(x3)), Eq(x1 + x2 + x3, 3)), (0, True))');
  });
  it("marginal_distribution(M, M[0])(x1).subs(x1, 1)", () => {
    const p1 = new Sym('p1', { positive: true });
    const x1 = new Sym('x1', { nonnegative: true, integer: true });
    const p2 = new Sym('p2', { positive: true });
    const p3 = new Sym('p3', { positive: true });
    expect(sympyStr(add(piecewise([mul(6, pow(p1, x1), pow(fn('factorial', [x1]), -1)), Relational(x1, rational(3), '==', { evaluate: false })], [rational(0), true]), piecewise([mul(pow(p1, x1), pow(p2, 3), pow(fn('factorial', [x1]), -1)), Relational(x1, rational(0), '==', { evaluate: false })], [rational(0), true]), piecewise([mul(pow(p1, x1), pow(p3, 3), pow(fn('factorial', [x1]), -1)), Relational(x1, rational(0), '==', { evaluate: false })], [rational(0), true]), piecewise([mul(3, pow(p1, x1), pow(p2, 2), pow(fn('factorial', [x1]), -1)), Relational(x1, rational(1), '==', { evaluate: false })], [rational(0), true]), piecewise([mul(3, pow(p1, x1), pow(p3, 2), pow(fn('factorial', [x1]), -1)), Relational(x1, rational(1), '==', { evaluate: false })], [rational(0), true]), piecewise([mul(6, p2, pow(p1, x1), pow(fn('factorial', [x1]), -1)), Relational(x1, rational(2), '==', { evaluate: false })], [rational(0), true]), piecewise([mul(6, p3, pow(p1, x1), pow(fn('factorial', [x1]), -1)), Relational(x1, rational(2), '==', { evaluate: false })], [rational(0), true]), piecewise([mul(3, p2, pow(p1, x1), pow(p3, 2), pow(fn('factorial', [x1]), -1)), Relational(x1, rational(0), '==', { evaluate: false })], [rational(0), true]), piecewise([mul(3, p3, pow(p1, x1), pow(p2, 2), pow(fn('factorial', [x1]), -1)), Relational(x1, rational(0), '==', { evaluate: false })], [rational(0), true]), piecewise([mul(6, p2, p3, pow(p1, x1), pow(fn('factorial', [x1]), -1)), Relational(x1, rational(1), '==', { evaluate: false })], [rational(0), true])).subs(x1, rational(1)))).toBe('3*p1*p2**2 + 6*p1*p2*p3 + 3*p1*p3**2');
  });
  it("density(B)(x, y)", () => {
    const [x, y] = symbols('x y');
    const a1 = new Sym('a1', { positive: true });
    const a2 = new Sym('a2', { positive: true });
    expect(sympyStr(new MultivariateBetaDistribution([ImmutableDenseMatrix(Matrix.of([[a1], [a2]]))]).call(x, y))).toBe('x**(a1 - 1)*y**(a2 - 1)*gamma(a1 + a2)/(gamma(a1)*gamma(a2))');
  });
  it("marginal_distribution(C, C[0])(x)", () => {
    const [C, x] = symbols('C x');
    const a2 = new Sym('a2', { positive: true });
    const a1 = new Sym('a1', { positive: true });
    expect(sympyStr(xreplace(mul(pow(a2, -1), pow(new IndexedBase(C, {}).at(rational(0)), add(-1, a1)), pow(fn('gamma', [a1]), -1), pow(fn('gamma', [a2]), -1), fn('gamma', [add(a1, a2)])), [[new IndexedBase(C, {}).at(rational(0)), x]]))).toBe('x**(a1 - 1)*gamma(a1 + a2)/(a2*gamma(a1)*gamma(a2))');
  });
  it("density(ed)(a1, a2)", () => {
    const a1 = new Sym('a1', { positive: true });
    const a2 = new Sym('a2', { positive: true });
    expect(sympyStr(new MultivariateEwensDistribution([rational(2), rational(1)]).call(a1, a2))).toBe('Piecewise((1/(2**a2*factorial(a1)*factorial(a2)), Eq(a1 + 2*a2, 2)), (0, True))');
  });
  it("marginal_distribution(ed, ed[0])(a1)", () => {
    const E = new Sym('E');
    const a1 = new Sym('a1', { positive: true });
    expect(sympyStr(xreplace(add(piecewise([pow(fn('factorial', [new IndexedBase(E, {}).at(rational(0))]), -1), Relational(new IndexedBase(E, {}).at(rational(0)), rational(2), '==', { evaluate: false })], [rational(0), true]), piecewise([mul(rational(1, 2), pow(fn('factorial', [new IndexedBase(E, {}).at(rational(0))]), -1)), Relational(new IndexedBase(E, {}).at(rational(0)), rational(0), '==', { evaluate: false })], [rational(0), true])), [[new IndexedBase(E, {}).at(rational(0)), a1]]))).toBe('Piecewise((1/factorial(a1), Eq(a1, 2)), (0, True))');
  });
  it("density(X)(y, z)", () => {
    const [y, z] = symbols('y z');
    expect(sympyStr(new MultivariateLaplaceDistribution([ImmutableDenseMatrix(Matrix.of([[rational(2)], [rational(4)]])), ImmutableDenseMatrix(Matrix.of([[rational(3), rational(1)], [rational(1), rational(3)]]))]).call(y, z))).toBe('sqrt(2)*exp(y/4 + 5*z/4)*besselk(0, sqrt(15*y*(3*y/8 - z/8)/2 + 15*z*(-y/8 + 3*z/8)/2))/(4*pi)');
  });
  it("density(X)(1, 2)", () => {
    expect(sympyStr(new MultivariateLaplaceDistribution([ImmutableDenseMatrix(Matrix.of([[rational(2)], [rational(4)]])), ImmutableDenseMatrix(Matrix.of([[rational(3), rational(1)], [rational(1), rational(3)]]))]).call(rational(1), rational(2)))).toBe('sqrt(2)*exp(11/4)*besselk(0, sqrt(165)/4)/(4*pi)');
  });
  it("density(X)(y, z) (2)", () => {
    const [y, z] = symbols('y z');
    expect(sympyStr(new MultivariateNormalDistribution([ImmutableDenseMatrix(Matrix.of([[rational(3)], [rational(4)]])), ImmutableDenseMatrix(Matrix.of([[rational(2), rational(1)], [rational(1), rational(2)]]))]).call(y, z))).toBe('sqrt(3)*exp(-y**2/3 + y*z/3 + 2*y/3 - z**2/3 + 5*z/3 - 13/3)/(6*pi)');
  });
  it("density(X)(1, 2) (2)", () => {
    expect(sympyStr(new MultivariateNormalDistribution([ImmutableDenseMatrix(Matrix.of([[rational(3)], [rational(4)]])), ImmutableDenseMatrix(Matrix.of([[rational(2), rational(1)], [rational(1), rational(2)]]))]).call(rational(1), rational(2)))).toBe('sqrt(3)*exp(-4/3)/(6*pi)');
  });
  it("marginal_distribution(X, X[1])(y)", () => {
    const [X, y] = symbols('X y');
    expect(sympyStr(xreplace(mul(rational(1, 2), pow(pi, rational(-1, 2)), exp(mul(rational(-1, 4), pow(add(-4, new IndexedBase(X, {}).at(rational(1))), 2)))), [[new IndexedBase(X, {}).at(rational(1)), y]]))).toBe('exp(-(y - 4)**2/4)/(2*sqrt(pi))');
  });
  it("marginal_distribution(X, X[0])(y)", () => {
    const [X, y] = symbols('X y');
    expect(sympyStr(xreplace(mul(rational(1, 2), pow(pi, rational(-1, 2)), exp(mul(rational(-1, 4), pow(add(-3, new IndexedBase(X, {}).at(rational(0))), 2)))), [[new IndexedBase(X, {}).at(rational(0)), y]]))).toBe('exp(-(y - 3)**2/4)/(2*sqrt(pi))');
  });
  it("density(X)(obs)", () => {
    const n = new Sym('n', { positive: true, integer: true });
    expect(sympyStr(new MultivariateNormalDistribution([new MatrixSymbol('mu', n, rational(1)), new MatrixSymbol('Sg', n, n)]).call(new MatrixSymbol('obs', n, rational(1))))).toBe('(exp(((1/2)*mu.T - (1/2)*obs.T)*Sg**(-1)*(-mu + obs))/sqrt((2*pi)**n*Determinant(Sg)))[0, 0]');
  });
  it("density(X)(1, 2) (3)", () => {
    expect(sympyStr(new MultivariateTDistribution([ImmutableDenseMatrix(Matrix.of([[rational(1)], [rational(1)]])), ImmutableDenseMatrix(Matrix.of([[rational(1), rational(0)], [rational(0), rational(1)]])), rational(2)]).call(rational(1), rational(2)))).toBe('2/(9*pi)');
  });
  it("density(N)(x1, x2, x3)", () => {
    const p1 = new Sym('p1', { positive: true });
    const p2 = new Sym('p2', { positive: true });
    const p3 = new Sym('p3', { positive: true });
    const x1 = new Sym('x1', { nonnegative: true, integer: true });
    const x2 = new Sym('x2', { nonnegative: true, integer: true });
    const x3 = new Sym('x3', { nonnegative: true, integer: true });
    expect(sympyStr(new NegativeMultinomialDistribution([rational(3), ImmutableDenseMatrix(Matrix.of([[p1], [p2], [p3]]))]).call(x1, x2, x3))).toBe('p1**x1*p2**x2*p3**x3*(-p1 - p2 - p3 + 1)**3*gamma(x1 + x2 + x3 + 3)/(2*factorial(x1)*factorial(x2)*factorial(x3))');
  });
  it("marginal_distribution(N_c, N_c[0])(1).evalf().round(2)", () => {
    expect(sympyStr(round(new Float({ man: 4525589859926015n, exp: -54n }, 53), 2))).toBe('0.25');
  });
  it("density(X)(y, z) (3)", () => {
    const [y, z] = symbols('y z');
    expect(sympyStr(new NormalGammaDistribution([rational(0), rational(1), rational(2), rational(3)]).call(y, z))).toBe('9*sqrt(2)*z**(3/2)*exp(-3*z)*exp(-y**2*z/2)/(2*sqrt(pi))');
  });
  it("marginal_distribution(m, m[0])(1)", () => {
    const X = new Sym('X');
    expect(sympyStr(xreplace(mul(rational(1, 2), pow(pi, rational(-1, 2)), exp(mul(rational(-1, 4), pow(add(-1, new IndexedBase(X, {}).at(rational(0))), 2)))), [[new IndexedBase(X, {}).at(rational(0)), rational(1)]]))).toBe('1/(2*sqrt(pi))');
  });
});
